719	/**
720	 * "Change folder…": the native folder picker, then the workspace is pointed at that folder.
721	 * Relocating never moves or copies files; the rules are in `relocate.ts` and the registry.
722	 */
723	async function relocateFolder(
724	  sender: Electron.WebContents,
725	  id: unknown,
726	): Promise<WorkspaceRelocateResult> {
727	  const reg = requireRegistry();
728	  const deps = { ...activeTransactionDeps(), registry: reg };
729	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
730	  // Locked or read-only: say so now, instead of after the user picked a folder.
731	  const refused = relocateRefusal(deps, id);
732	  if (refused) return refused;
733	  const entry = reg.get(id);
734	  if (!entry) return { ok: false, reason: "unknown" };
735	
736	  const window = BrowserWindow.fromWebContents(sender);
737	  const t = createMainTranslator(getAppSettings().locale);
738	  const options: Electron.OpenDialogOptions = {
739	    title: t("dialogs.relocateWorkspace", { name: entry.name }),
740	    buttonLabel: t("dialogs.relocateWorkspaceButton"),
741	    // Where it was: a moved folder is usually next to where it used to be.
742	    defaultPath: dirname(entry.path),
743	    properties: ["openDirectory", "createDirectory"],
744	  };
745	  const picked = window
